#include <bits/stdc++.h>
using namespace std;

const long long mod = 998244353;

long long recursiveFn(long long x, long long y, long long total, int type, vector<map<long long, long long>> &memo) {
    if (memo[type].count(total)) {
        return memo[type][total];
    }
    if (total == 1) {
        return (type == 0) ? x : y;
    }
    if (total % 2 == 1) {
        long long res = (x * recursiveFn(x, y, total - 1, type, memo) + y * recursiveFn(x, y, total - 1, (type + 1) % 2, memo)) % mod;
        return res;
    } else {
        long long half = total / 2;
        long long ch = recursiveFn(x, y, half, 0, memo);
        long long nch = recursiveFn(x, y, half, 1, memo);
        long long ans;
        if (type == 0) {
            ans = (ch * ch + nch * nch) % mod;
        } else {
            ans = (2 * ch * nch) % mod;
        }
        memo[type][total] = ans;
        return ans;
    }
}

long long binomial(long long x, long long st) {
    if (st == 0) return 1;
    if (st == 1) return x;
    long long half = st / 2;
    long long res = binomial(x, half);
    if (st % 2 == 0) {
        return (res * res) % mod;
    } else {
        return (((res * res) % mod) * x) % mod;
    }
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    long long n, m, p, q;
    cin >> n >> m >> p >> q;
    long long segmentLength = q - p + 1;
    if (p % 2 == 0) {
        segmentLength -= segmentLength / 2;
    } else {
        segmentLength /= 2;
    }
    long long otherSegment = (q - p + 1) - segmentLength;
    vector<map<long long, long long>> memo[2];
    memo[0] = vector<map<long long, long long>>(1);
    memo[1] = vector<map<long long, long long>>(1);
    if (((n & m) % 2) == 0) {
        long long answer = recursiveFn(segmentLength, otherSegment, n * m, 0, vector<map<long long, long long>>{memo[0], memo[1]});
        cout << answer << "\n";
    } else {
        long long answer = binomial(segmentLength + otherSegment, n * m);
        cout << answer << "\n";
    }
    return 0;
}

